import{_ as i,o as s,c as a,a0 as e}from"./chunks/framework.DQOulFGV.js";const l="data:image/svg+xml;base64,",y=JSON.parse('{"title":"第4章 分布式锁","description":"","frontmatter":{},"headers":[],"relativePath":"redis/04-high-availability/chapter-04-distributed-lock.md","filePath":"redis/04-high-availability/chapter-04-distributed-lock.md"}'),n={name:"redis/04-high-availability/chapter-04-distributed-lock.md"};function d(h,t,p,k,r,g){return s(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="第4章-分布式锁" tabindex="-1">第4章 分布式锁 <a class="header-anchor" href="#第4章-分布式锁" aria-label="Permalink to &quot;第4章 分布式锁&quot;">​</a></h1><blockquote><p>在分布式环境下，多个进程要互斥访问共享资源，单机锁失效，需要分布式锁。本章从 SETNX 的坑讲起，逐步演进到 Redisson 看门狗与 RedLock。</p></blockquote><hr><h2 id="_4-1-setnx-的问题" tabindex="-1">4.1 SETNX 的问题 <a class="header-anchor" href="#_4-1-setnx-的问题" aria-label="Permalink to &quot;4.1 SETNX 的问题&quot;">​</a></h2><p>最早的实现用 <code>SETNX</code>（SET if Not eXists）加锁，但存在三个致命问题：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 有问题的实现</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">redis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setnx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lock&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 加锁</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ... 业务逻辑 ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">redis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">del</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lock&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 释放锁</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">死锁</td><td style="text-align:left;">加锁后进程崩溃，锁永远无法释放</td></tr><tr><td style="text-align:left;">误删</td><td style="text-align:left;">A 的锁过期了，B 拿到锁，A 却删了 B 的锁</td></tr><tr><td style="text-align:left;">非原子</td><td style="text-align:left;">加锁与设置过期时间分两步，非原子</td></tr></tbody></table><p>这些问题在并发场景下会导致锁失效或死锁。</p><hr><h2 id="_4-2-原子加锁与释放" tabindex="-1">4.2 原子加锁与释放 <a class="header-anchor" href="#_4-2-原子加锁与释放" aria-label="Permalink to &quot;4.2 原子加锁与释放&quot;">​</a></h2><p>Redis 2.6.12 起，<code>SET</code> 命令支持 <code>NX</code> 和 <code>PX</code> 参数，把「加锁 + 设置过期」合并为一条原子命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lock:order</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uuid</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30000</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>NX</code></td><td style="text-align:left;">不存在才设置（加锁）</td></tr><tr><td style="text-align:left;"><code>PX 30000</code></td><td style="text-align:left;">30 秒后自动过期（防死锁）</td></tr><tr><td style="text-align:left;"><code>uuid</code></td><td style="text-align:left;">唯一标识，标识锁的持有者</td></tr></tbody></table><h3 id="释放锁-用-lua-保证原子" tabindex="-1">释放锁：用 Lua 保证原子 <a class="header-anchor" href="#释放锁-用-lua-保证原子" aria-label="Permalink to &quot;释放锁：用 Lua 保证原子&quot;">​</a></h3><p>释放锁前要校验「锁是我持有的」，防止误删。校验 + 删除必须原子，用 Lua 脚本实现：</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 只有 value 匹配（是我自己的锁）才删除</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redis.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, KEYS[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ARGV[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redis.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;del&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, KEYS[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Java 伪代码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String script </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;if redis.call(&#39;get&#39;,KEYS[1])==ARGV[1] then return redis.call(&#39;del&#39;,KEYS[1]) else return 0 end&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jedis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(script, List.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lock:order&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), List.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(uuid));</span></span></code></pre></div><p>这样解决了「死锁」「误删」「非原子」三个问题。</p><hr><h2 id="_4-3-redisson" tabindex="-1">4.3 Redisson <a class="header-anchor" href="#_4-3-redisson" aria-label="Permalink to &quot;4.3 Redisson&quot;">​</a></h2><p>Redisson 是 Java 的 Redis 客户端，封装了分布式锁，提供可重入锁、自动续期等能力。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RLock lock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redisson.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getLock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lock:order&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    lock.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 加锁，默认 30 秒，自动续期</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ... 业务逻辑 ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">finally</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    lock.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unlock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 释放锁</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Redisson 的锁相对手写 <code>SET NX PX</code> 的改进：</p><table tabindex="0"><thead><tr><th style="text-align:left;">能力</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">可重入</td><td style="text-align:left;">同一个线程可重复加锁</td></tr><tr><td style="text-align:left;">自动续期</td><td style="text-align:left;">看门狗自动延长锁的过期时间</td></tr><tr><td style="text-align:left;">阻塞获取</td><td style="text-align:left;">未拿到锁时阻塞等待，而非直接失败</td></tr><tr><td style="text-align:left;">公平锁</td><td style="text-align:left;">按请求顺序获取</td></tr></tbody></table><hr><h2 id="_4-4-看门狗机制" tabindex="-1">4.4 看门狗机制 <a class="header-anchor" href="#_4-4-看门狗机制" aria-label="Permalink to &quot;4.4 看门狗机制&quot;">​</a></h2><p>手写锁的隐患：业务执行超过锁的过期时间，锁会提前释放，其他线程拿到锁导致并发。Redisson 的「看门狗（Watchdog）」自动续期解决这个问题。</p><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><p><img src="`+l+`" alt="Redisson 看门狗续期机制"></p><table tabindex="0"><thead><tr><th style="text-align:left;">概念</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">默认超时</td><td style="text-align:left;">锁默认 30 秒</td></tr><tr><td style="text-align:left;">续期间隔</td><td style="text-align:left;">每 10 秒（超时的 1/3）续期一次</td></tr><tr><td style="text-align:left;">续期逻辑</td><td style="text-align:left;">只要线程还持有锁，就把过期时间重置为 30 秒</td></tr><tr><td style="text-align:left;">释放后停止</td><td style="text-align:left;">线程释放锁后，看门狗停止续期</td></tr></tbody></table><p>这样即使业务执行超过 30 秒，锁也不会过期，直到业务完成主动释放。</p><blockquote><p>看门狗只在「不手动指定 leaseTime」时生效。若手动指定了过期时间（如 <code>lock.lock(10, TimeUnit.SECONDS)</code>），则不会自动续期。</p></blockquote><hr><h2 id="_4-5-redlock" tabindex="-1">4.5 RedLock <a class="header-anchor" href="#_4-5-redlock" aria-label="Permalink to &quot;4.5 RedLock&quot;">​</a></h2><p>单节点的分布式锁在「节点宕机」时会失效（锁数据丢失）。RedLock 通过多节点容错来提升可靠性。</p><h3 id="原理-1" tabindex="-1">原理 <a class="header-anchor" href="#原理-1" aria-label="Permalink to &quot;原理&quot;">​</a></h3><p>RedLock 在 N 个独立的 Redis 节点上分别加锁，客户端需要在超过半数（N/2+1）的节点上成功加锁，才算获取锁成功。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>N=5 个独立节点</span></span>
<span class="line"><span>加锁：依次向 5 个节点请求加锁，至少 3 个成功才算获取锁</span></span>
<span class="line"><span>释放：向所有节点释放锁</span></span></code></pre></div><h3 id="争议" tabindex="-1">争议 <a class="header-anchor" href="#争议" aria-label="Permalink to &quot;争议&quot;">​</a></h3><p>RedLock 由 Redis 作者 antirez 提出，但也引发了较多争议：</p><table tabindex="0"><thead><tr><th style="text-align:left;">观点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">支持方</td><td style="text-align:left;">多节点容错，单节点宕机不影响锁可用性</td></tr><tr><td style="text-align:left;">质疑方</td><td style="text-align:left;">无法解决时钟跳跃、GC 停顿、网络分区等极端问题</td></tr></tbody></table><p>争议的核心：RedLock 依赖节点间时钟同步，而分布式系统里时钟并不完全可靠，极端情况下（GC 长时间停顿、时钟回拨）仍可能出现锁失效。</p><h3 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">建议</th></tr></thead><tbody><tr><td style="text-align:left;">一般业务</td><td style="text-align:left;">单节点 Redis + Redisson 即可</td></tr><tr><td style="text-align:left;">极高可靠性要求</td><td style="text-align:left;">可考虑 RedLock，但需理解其局限</td></tr><tr><td style="text-align:left;">更强一致性</td><td style="text-align:left;">考虑 ZooKeeper、etcd 等基于共识算法的方案</td></tr></tbody></table><hr><h2 id="_4-6-最佳实践" tabindex="-1">4.6 最佳实践 <a class="header-anchor" href="#_4-6-最佳实践" aria-label="Permalink to &quot;4.6 最佳实践&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">实践</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">用成熟客户端</td><td style="text-align:left;">优先用 Redisson，别手写锁</td></tr><tr><td style="text-align:left;">锁要有超时</td><td style="text-align:left;">任何锁都要有过期时间，防死锁</td></tr><tr><td style="text-align:left;">校验再释放</td><td style="text-align:left;">释放前校验持有者，防误删</td></tr><tr><td style="text-align:left;">锁粒度要小</td><td style="text-align:left;">锁的范围尽量小，减少竞争</td></tr><tr><td style="text-align:left;">业务要幂等</td><td style="text-align:left;">分布式锁不能保证绝对互斥，业务要幂等兜底</td></tr></tbody></table>`,47)])])}const c=i(n,[["render",d]]);export{y as __pageData,c as default};
